-- Activate only after publishing compatible user clients. Preserve all denies/presets.
ALTER TABLE public.user_files ENABLE ROW LEVEL SECURITY;
DO $p$DECLARE p record;BEGIN FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='user_files' AND permissive='PERMISSIVE' AND ('authenticated'=ANY(roles) OR 'public'=ANY(roles)) LOOP EXECUTE format('DROP POLICY %I ON public.user_files',p.policyname);END LOOP;END $p$;
CREATE POLICY shared_view ON public.user_files FOR SELECT TO authenticated USING(public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','view',ARRAY[owner_id])) ;
CREATE POLICY shared_create ON public.user_files FOR INSERT TO authenticated  WITH CHECK(public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','create',ARRAY[owner_id]) AND public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','view',ARRAY[owner_id]) AND owner_id=auth.uid());
CREATE POLICY shared_update ON public.user_files FOR UPDATE TO authenticated USING(public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','update',ARRAY[owner_id]) AND public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','view',ARRAY[owner_id])) WITH CHECK(public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','update',ARRAY[owner_id]) AND public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','view',ARRAY[owner_id]));
CREATE POLICY shared_delete ON public.user_files FOR DELETE TO authenticated USING(public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','delete',ARRAY[owner_id]) AND public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.files','view',ARRAY[owner_id])) ;
CREATE TRIGGER zzzz_shared_structure BEFORE INSERT OR UPDATE ON public.user_files FOR EACH ROW EXECUTE FUNCTION public.shared_structure_guard();
