ALTER FUNCTION public.global_search_activity_body_ids(text,integer) SECURITY INVOKER;
CREATE OR REPLACE FUNCTION public.is_chat_member(_conv uuid,_user uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT coalesce(_user=auth.uid() AND public.shared_chat_access(_conv,'view'),false) $$;
REVOKE ALL ON FUNCTION public.is_chat_member(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_chat_member(uuid,uuid) TO authenticated;
-- No direct membership, tenant, sender or attachment reassignment path bypasses the atomic RPC.
REVOKE INSERT,UPDATE,DELETE ON public.chat_conversations,public.chat_conversation_members,public.chat_messages,public.chat_message_attachments FROM PUBLIC,anon,authenticated;
GRANT UPDATE(last_read_at,muted) ON public.chat_conversation_members TO authenticated;
DO $p$DECLARE p record;BEGIN FOR p IN SELECT policyname,tablename FROM pg_policies WHERE schemaname='public' AND tablename IN('chat_conversation_members','chat_messages','chat_message_attachments','chat_conversations') AND permissive='PERMISSIVE' AND ('authenticated'=ANY(roles) OR 'public'=ANY(roles)) LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename);END LOOP;END $p$;
CREATE POLICY shared_chat_read ON public.chat_conversations FOR SELECT TO authenticated USING(shared_chat_access(id));
CREATE POLICY shared_chat_read ON public.chat_conversation_members FOR SELECT TO authenticated USING(shared_chat_access(conversation_id));
CREATE POLICY shared_chat_self ON public.chat_conversation_members FOR UPDATE TO authenticated USING(user_id=auth.uid() AND shared_chat_access(conversation_id)) WITH CHECK(user_id=auth.uid() AND shared_chat_access(conversation_id));
CREATE POLICY shared_chat_read ON public.chat_messages FOR SELECT TO authenticated USING(shared_chat_access(conversation_id));
CREATE POLICY shared_chat_read ON public.chat_message_attachments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM chat_messages m WHERE m.id=message_id));
CREATE OR REPLACE FUNCTION public.user_files_used_bytes(uid uuid)
RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN IF uid IS DISTINCT FROM auth.uid() OR work_access_context()->>'actor' IS NULL THEN RAISE EXCEPTION 'Cota indisponível.' USING ERRCODE='42501';END IF;RETURN (SELECT coalesce(sum(size_bytes),0)::bigint FROM user_files WHERE owner_id=uid);END $$;
REVOKE ALL ON FUNCTION public.user_files_used_bytes(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.user_files_used_bytes(uuid) TO authenticated;
CREATE POLICY shared_source_read ON public.search_recent AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() AND shared_search_item_access(entity_type,entity_id));
CREATE POLICY shared_source_insert ON public.search_recent AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT public.is_read_only_view() AND shared_search_item_access(entity_type,entity_id));
CREATE POLICY shared_source_update ON public.search_recent AS RESTRICTIVE FOR UPDATE TO authenticated USING(user_id=auth.uid() AND NOT public.is_read_only_view()) WITH CHECK(user_id=auth.uid() AND shared_search_item_access(entity_type,entity_id));
CREATE POLICY shared_source_read ON public.search_pinned AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() AND shared_search_item_access(entity_type,entity_id));
CREATE POLICY shared_source_insert ON public.search_pinned AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT public.is_read_only_view() AND shared_search_item_access(entity_type,entity_id));
CREATE POLICY shared_source_update ON public.search_pinned AS RESTRICTIVE FOR UPDATE TO authenticated USING(user_id=auth.uid() AND NOT public.is_read_only_view()) WITH CHECK(user_id=auth.uid() AND shared_search_item_access(entity_type,entity_id));

-- Protect security JSON and data region against direct column access, as with payment/NFS-e settings.
REVOKE SELECT(security_settings,data_region),INSERT(security_settings,data_region),UPDATE(security_settings,data_region) ON public.workspaces FROM PUBLIC,anon,authenticated;
CREATE POLICY shared_workspace_config ON public.workspaces AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.shared_context_access((SELECT public.work_access_context()),id,'system.settings','manage',ARRAY[]::uuid[])) WITH CHECK(public.shared_context_access((SELECT public.work_access_context()),id,'system.settings','manage',ARRAY[]::uuid[]));
CREATE POLICY shared_ip_log ON public.ip_access_log AS RESTRICTIVE FOR SELECT TO authenticated USING(public.shared_context_access((SELECT public.work_access_context()),workspace_id,'system.settings','view',ARRAY[]::uuid[]));

DO $columns$ DECLARE cols text;BEGIN
 SELECT string_agg(quote_ident(attname),',' ORDER BY attnum) INTO cols FROM pg_attribute WHERE attrelid='public.user_files'::regclass AND attnum>0 AND NOT attisdropped AND attname<>'public_token';
 REVOKE SELECT ON public.user_files FROM PUBLIC,anon,authenticated;
 REVOKE SELECT(public_token) ON public.user_files FROM PUBLIC,anon,authenticated;
 EXECUTE format('GRANT SELECT(%s) ON public.user_files TO authenticated',cols);
END $columns$;

DO $p$DECLARE p record;BEGIN FOR p IN SELECT policyname,tablename FROM pg_policies WHERE schemaname='public' AND tablename IN('media_assets','module_branding') AND permissive='PERMISSIVE' AND ('authenticated'=ANY(roles) OR 'public'=ANY(roles)) LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename);END LOOP;END $p$;
CREATE POLICY shared_media_read ON public.media_assets FOR SELECT TO authenticated USING(shared_context_access((SELECT work_access_context()),workspace_id,'system.media','view',ARRAY[owner_user_id]));
REVOKE INSERT,UPDATE,DELETE ON public.media_assets FROM PUBLIC,anon,authenticated;
