CREATE POLICY shared_module_branding_insert ON public.module_branding FOR INSERT TO authenticated WITH CHECK(shared_context_access((SELECT work_access_context()),workspace_id,'system.branding','update',ARRAY[]::uuid[]));
CREATE POLICY shared_module_branding_update ON public.module_branding FOR UPDATE TO authenticated USING(shared_context_access((SELECT work_access_context()),workspace_id,'system.branding','update',ARRAY[]::uuid[])) WITH CHECK(shared_context_access((SELECT work_access_context()),workspace_id,'system.branding','update',ARRAY[]::uuid[]));

CREATE POLICY shared_ai_settings ON public.workspace_ai_settings AS RESTRICTIVE FOR SELECT TO authenticated USING(shared_context_access((SELECT work_access_context()),workspace_id,'system.ai_settings','view',ARRAY[]::uuid[]));
CREATE POLICY shared_ai_logs ON public.ai_call_logs AS RESTRICTIVE FOR SELECT TO authenticated USING(shared_context_access((SELECT work_access_context()),workspace_id,'system.ai_settings','view',ARRAY[]::uuid[]));
-- Module activation and paid entitlement are distinct. Existing administrative/business
-- constraints still apply in addition to these restrictive policies.
CREATE POLICY shared_module_update ON public.workspace_modules AS RESTRICTIVE FOR UPDATE TO authenticated USING(shared_context_access((SELECT work_access_context()),workspace_id,'system.modules','update',ARRAY[]::uuid[])) WITH CHECK(shared_context_access((SELECT work_access_context()),workspace_id,'system.modules','update',ARRAY[]::uuid[]));
CREATE POLICY shared_module_insert ON public.workspace_modules AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(shared_context_access((SELECT work_access_context()),workspace_id,'system.modules','update',ARRAY[]::uuid[]));
CREATE OR REPLACE FUNCTION public.shared_module_entitlement_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF auth.uid() IS NOT NULL AND NOT is_platform_admin(auth.uid()) AND (TG_OP='INSERT' OR NEW.plan_code IS DISTINCT FROM OLD.plan_code OR NEW.module_id IS DISTINCT FROM OLD.module_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id) THEN RAISE EXCEPTION 'Plano e contratação são operações da plataforma.' USING ERRCODE='42501';END IF;RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.shared_module_entitlement_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zzzz_shared_module_entitlement BEFORE INSERT OR UPDATE ON public.workspace_modules FOR EACH ROW EXECUTE FUNCTION public.shared_module_entitlement_guard();

CREATE POLICY shared_ai_log_read ON public.ai_call_logs FOR SELECT TO authenticated USING(shared_context_access((SELECT work_access_context()),workspace_id,'system.ai_settings','view',ARRAY[]::uuid[]));
